function safeStore(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Device storage is full. Download a project backup.');return false}}
function readStore(key){try{return JSON.parse(localStorage.getItem(key))||[]}catch{return []}}
function cameraAt(s,t){const a=s.camera?.start||{zoom:1,x:480,y:270},b=s.camera?.end||a;let f=Math.max(0,Math.min(1,t/s.duration));f=f*f*(3-2*f);return {zoom:a.zoom+(b.zoom-a.zoom)*f,x:a.x+(b.x-a.x)*f,y:a.y+(b.y-a.y)*f}}
function applyCamera(c,s,t){const v=cameraAt(s,t);c.translate(480,270);c.scale(v.zoom,v.zoom);c.translate(-v.x,-v.y)}
function scenePoint(e){const r=$('stage').getBoundingClientRect(),v=cameraAt(current(),time);return {x:((e.clientX-r.left)*960/r.width-480)/v.zoom+v.x,y:((e.clientY-r.top)*540/r.height-270)/v.zoom+v.y}}
function loadImage(src){let im=images.get(src);if(!im){im=new Image();images.set(src,im);im.onload=draw;im.src=src}return im}
function drawBackground(c,s){if(!s.backgroundImage)return;const im=loadImage(s.backgroundImage);if(!im.complete||!im.naturalWidth)return;const f=(s.backgroundFit==='contain'?Math.min:Math.max)(960/im.width,540/im.height);c.drawImage(im,(960-im.width*f)/2,(540-im.height*f)/2,im.width*f,im.height*f)}
function drawCaptions(c,s,t){const lines=(s.captions||[]).filter(x=>t>=x.start&&t<x.end);if(!lines.length)return;c.save();c.font='600 25px sans-serif';c.textAlign='center';const words=lines.map(x=>x.text).join(' ').split(/\s+/),wrapped=[''];for(const w of words){let n=wrapped.length-1;if(c.measureText(wrapped[n]+' '+w).width>820&&wrapped[n])wrapped.push(w);else wrapped[n]+=(wrapped[n]?' ':'')+w}const shown=wrapped.slice(0,3),height=shown.length*32+18;rect(c,45,520-height,870,height,'rgba(20,32,29,.87)',8);c.fillStyle='#fffaf0';shown.forEach((l,i)=>c.fillText(l,480,520-height+32+i*32));c.restore()}
function drawGuides(c){if(recording||!guideLines.length)return;c.save();applyCamera(c,current(),time);c.setLineDash([5,4]);for(const g of guideLines)line(c,g.axis==='x'?g.value:0,g.axis==='y'?g.value:0,g.axis==='x'?g.value:960,g.axis==='y'?g.value:540,'#dc7254',1);c.restore()}
function lipExpression(o,t){if(!o.lipSync||!narrationBuffer)return o.expression;const at=sceneOffset()+t;const data=narrationBuffer.getChannelData(0),start=Math.floor(at*narrationBuffer.sampleRate);let sum=0,n=0;for(let i=start;i<Math.min(data.length,start+1024);i+=8){sum+=data[i]*data[i];n++}return n&&Math.sqrt(sum/n)>.025?'talk':o.expression==='talk'?'happy':o.expression}
function drawWaveform(){const canvas=$('waveform');if(!canvas)return;const c=canvas.getContext('2d');c.clearRect(0,0,960,72);c.fillStyle='#edf1e8';c.fillRect(0,0,960,72);for(const [buffer,color,mid] of [[narrationBuffer,'#54766a',22],[musicBuffer,'#c78c45',53]]){if(!buffer)continue;const data=buffer.getChannelData(0),offset=sceneOffset();c.strokeStyle=color;c.beginPath();for(let x=0;x<960;x++){let a=Math.floor((offset+x/960*current().duration)*buffer.sampleRate),b=Math.min(data.length,Math.floor((offset+(x+1)/960*current().duration)*buffer.sampleRate)),max=0;for(let i=a;i<b;i+=Math.max(1,Math.floor((b-a)/30)))max=Math.max(max,Math.abs(data[i]));c.moveTo(x,mid-max*20);c.lineTo(x,mid+max*20)}c.stroke()}line(c,time/current().duration*960,0,time/current().duration*960,72,'#b8522d',2)}
function renderExtras(){if(!$('captions'))return;const s=current(),o=object();$('bgFit').value=s.backgroundFit||'cover';$('captions').value=(s.captions||[]).map(x=>`${x.start} | ${x.end} | ${x.text}`).join('\n');$('groupName').value=o?.group||'';$('lipSync').checked=!!o?.lipSync;$('lipSync').disabled=o?.type!=='character'||!!o?.locked;for(const id of ['alignX','alignY','hideLayer','assignGroup','groupName','savedMotions','duplicate','remove','front','back','addKey'])$(id).disabled=!o||!!o.locked;const cam=s.camera?.[$('cameraEnd').value]||{zoom:1,x:480,y:270};$('cameraZoom').value=cam.zoom;$('cameraX').value=cam.x;$('cameraY').value=cam.y;document.querySelectorAll('#layers .layer').forEach((b,i)=>{const item=s.objects.slice().reverse()[i];b.textContent=(item.locked?'🔒 ':item.hidden?'◌ ':'')+(item.type==='character'?'◉ ':item.type==='text'?'T ':'◇ ')+item.name+(item.group?' · '+item.group:'')});$('controls').querySelectorAll('input,select,button').forEach(e=>e.disabled=!!o?.locked);drawWaveform()}
$('bgFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>12e6)return toast('Use a background smaller than 12 MB.');try{const src=await dataURL(file),im=await imageReady(src);const c=document.createElement('canvas'),f=Math.min(1,3840/im.width,2160/im.height);c.width=Math.round(im.width*f);c.height=Math.round(im.height*f);c.getContext('2d').drawImage(im,0,0,c.width,c.height);current().backgroundImage=c.toDataURL('image/jpeg',.88);save();draw();toast('Background added. Camera controls can pan and zoom across it.')}catch{toast('This image could not be opened. Try PNG or JPEG.')}};
function dataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
function imageReady(src){const cached=images.get(src);if(cached?.complete&&cached.naturalWidth)return Promise.resolve(cached);return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images.set(src,im);resolve(im)};im.onerror=reject;im.src=src})}
$('bgFit').onchange=e=>{current().backgroundFit=e.target.value;save();draw()};$('removeBg').onclick=()=>{delete current().backgroundImage;save();draw()};
$('cameraEnd').onchange=renderExtras;for(const id of ['cameraZoom','cameraX','cameraY'])$(id).oninput=()=>{stop();const s=current();s.camera??={start:{zoom:1,x:480,y:270},end:{zoom:1,x:480,y:270}};s.camera[$('cameraEnd').value]={zoom:+$('cameraZoom').value,x:+$('cameraX').value,y:+$('cameraY').value};time=$('cameraEnd').value==='start'?0:s.duration;save();draw()};$('resetCamera').onclick=()=>{delete current().camera;save();render()};
function align(axis){const o=object();if(!o)return toast('Select a layer first.');if(o.locked)return toast('Unlock this layer before editing.');const v=stateAt(o,time);v[axis]=axis==='x'?480:270;setKey(o,v);render()}
$('alignX').onclick=()=>align('x');$('alignY').onclick=()=>align('y');$('snapping').onchange=e=>snapEnabled=e.target.checked;
$('lockLayer').onclick=()=>{const o=object();if(!o)return;o.locked=!o.locked;save();render()};$('hideLayer').onclick=()=>{const o=object();if(!o||o.locked)return;o.hidden=!o.hidden;save();render()};$('assignGroup').onclick=()=>{const o=object();if(!o||o.locked)return;o.group=$('groupName').value.trim();save();render()};
// Store one undo entry per drag, with group translation evaluated from original states.
$('stage').onpointerdown=e=>{if(recording)return;stop();const p=scenePoint(e),o=current().objects.slice().reverse().find(o=>{if(o.hidden||o.locked||(typeof visibleAt==='function'&&!visibleAt(o,time)))return false;const b=bounds(o,stateAt(o,time));return p.x>=b.x&&p.x<=b.x+b.w&&p.y>=b.y&&p.y<=b.y+b.h});selected=o?.id||null;drag=null;if(o){const members=o.group?current().objects.filter(x=>x.group===o.group):[o];if(!members.some(x=>x.locked)){drag={o,p,items:members.map(x=>({o:x,v:typeof rawStateAt==='function'?rawStateAt(x,time):stateAt(x,time)}))};$('stage').setPointerCapture(e.pointerId)}}render()};
$('stage').onpointermove=e=>{if(!drag)return;const p=scenePoint(e),primary=drag.items.find(x=>x.o===drag.o);let dx=p.x-drag.p.x,dy=p.y-drag.p.y;guideLines=[];if(snapEnabled){for(const axis of ['x','y']){const targets=[axis==='x'?480:270,...current().objects.filter(o=>!drag.items.some(i=>i.o===o)&&!o.hidden).map(o=>stateAt(o,time)[axis])];const value=primary.v[axis]+(axis==='x'?dx:dy),target=targets.find(t=>Math.abs(t-value)<7/cameraAt(current(),time).zoom);if(target!==undefined){if(axis==='x')dx=target-primary.v.x;else dy=target-primary.v.y;guideLines.push({axis,value:target})}}}for(const item of drag.items){const v={...item.v,x:item.v.x+dx,y:item.v.y+dy},t=Math.round(time*100)/100,k=item.o.keys.find(k=>Math.abs(k.t-t)<.015);if(k)k.v=v;else item.o.keys.push({t,v});item.o.keys.sort((a,b)=>a.t-b.t)}draw()};
$('stage').onpointerup=$('stage').onpointercancel=()=>{if(drag){drag=null;guideLines=[];save();render()}};
function templateObject(type,extra,x,y,scale=1){return {id:uid(),type,name:extra.text||type,ease:'smooth',keys:[{t:0,v:{...pose,x,y,scale}}],...extra}}
document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>{stop();const s=scene({intro:'Opening title',compare:'Compare ideas',process:'Three steps',presenter:'Presenter & object'}[b.dataset.template]);const text=(t,x,y,size=38)=>templateObject('text',{text:t,fontSize:size,color:'#31564d'},x,y);s.objects.push(text(s.name,480,100));if(b.dataset.template==='intro')s.objects.push(text('Your explanation starts here',480,285,48),text('A new perspective, one idea at a time.',480,345,24));if(b.dataset.template==='compare')s.objects.push(text('Idea A',260,220),text('Idea B',700,220),templateObject('laptop',{},260,350),templateObject('coin',{},700,330));if(b.dataset.template==='process')for(let i=0;i<3;i++){s.objects.push(text('0'+(i+1),180+i*300,250,58),text(['Discover','Understand','Apply'][i],180+i*300,330,28));if(i<2)s.objects.push(templateObject('arrow',{},330+i*300,260,.6))}if(b.dataset.template==='presenter'){s.template='studio';s.objects.push(templateObject('character',{character:structuredClone(project.cast[0]||baseChar),expression:'happy'},250,460),templateObject('laptop',{},650,330,1.4))}project.scenes.push(s);sceneIndex=project.scenes.length-1;selected=null;time=0;save();render()});
function renderSavedScenes(){const list=readStore('elleson-scenes');$('savedScenes').replaceChildren();list.forEach((s,i)=>{const b=document.createElement('button');b.textContent='＋ '+s.name;b.onclick=()=>{stop();const copy=structuredClone(s);copy.id=uid();const objectIds=new Map();copy.objects.forEach(o=>{const old=o.id;o.id=uid();objectIds.set(old,o.id)});if(typeof remapStoryReferences==='function')remapStoryReferences({scenes:[copy],audio:[]},objectIds,new Map(),new Map([[s.id,copy.id]]));project.scenes.push(copy);sceneIndex=project.scenes.length-1;selected=null;time=0;save();render()};$('savedScenes').append(b)})}
$('saveScene').onclick=()=>{const a=readStore('elleson-scenes');a.push(structuredClone(current()));if(safeStore('elleson-scenes',a)){renderSavedScenes();toast('Scene saved to your presets.')}};
function renderMotions(){const select=$('savedMotions');select.innerHTML='<option value="">Saved actions</option>';readStore('elleson-motions').forEach((m,i)=>{const o=document.createElement('option');o.value=i;o.textContent=m.name;select.append(o)})}
$('saveMotion').onclick=()=>{const o=object();if(!o)return toast('Select an animated layer.');const name=prompt('Name this reusable action:',o.name+' action');if(!name)return;const a=readStore('elleson-motions');a.push({name,keys:structuredClone(o.keys)});if(safeStore('elleson-motions',a))renderMotions()};
$('savedMotions').onchange=e=>{const o=object(),m=readStore('elleson-motions')[+e.target.value];if(e.target.value===''||!o||o.locked)return;e.target.value='';const base=stateAt(o,time),first=m.keys[0],last=m.keys.at(-1),span=last.t-first.t;if(time+span>current().duration)return toast('Move earlier or lengthen the scene to fit this action.');const keys=m.keys.map(k=>({t:time+k.t-first.t,v:{...k.v,x:base.x+k.v.x-first.v.x,y:base.y+k.v.y-first.v.y}}));o.keys=o.keys.filter(k=>k.t<time||k.t>time+span).concat(keys).sort((a,b)=>a.t-b.t);save();render()};
function showProjects(){stop();renderProjects();$('projectDialog').showModal()}
$('projects').onclick=showProjects;$('closeProjects').onclick=()=>$('projectDialog').close();
function renderProjects(){$('projectList').replaceChildren();readStore('elleson-projects').forEach(entry=>{const row=document.createElement('div');row.className='project-entry';const open=document.createElement('button');open.textContent=entry.project.title+' · '+entry.project.scenes.length+' scenes';open.onclick=()=>{if(!confirm('Open this project? Save or download current changes first.'))return;loadProject(structuredClone(entry.project));$('projectDialog').close()};const del=document.createElement('button');del.textContent='Delete';del.onclick=()=>{if(confirm('Delete this saved project?')){safeStore('elleson-projects',readStore('elleson-projects').filter(x=>x.id!==entry.id));renderProjects()}};row.append(open,del);$('projectList').append(row)})}
$('saveProject').onclick=()=>{save();project.projectId??=uid();const a=readStore('elleson-projects'),entry={id:project.projectId,project:structuredClone(project)};const i=a.findIndex(x=>x.id===entry.id);if(i<0)a.push(entry);else a[i]=entry;if(safeStore('elleson-projects',a)){renderProjects();toast('Project saved to dashboard.')}};
function loadProject(p){if(!valid(p))throw Error('Invalid project');stop();project=p;sceneIndex=0;time=0;selected=null;clearAudio();clearMusic();narrationBuffer=null;narrationFile=null;historyStack=[JSON.stringify(p)];futureStack=[];$('title').value=p.title;save();renderCast();render()}
$('newProject').onclick=()=>{if(!confirm('Start a new project? Save or download the current one first.'))return;loadProject({version:1,title:'Untitled explanation',cast:[{id:uid(),...baseChar}],scenes:[scene('Scene 1')]});$('projectDialog').close()};
$('open').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{const p=JSON.parse(await f.text());if(!valid(p))throw Error();loadProject(p);toast('Project opened. Reattach narration and music.')}catch{toast('This is not a supported Elleson Studio project.')}};
$('applyCaptions').onclick=()=>{try{const a=$('captions').value.split('\n').filter(x=>x.trim()).map(l=>{const [start,end,...text]=l.split('|');return {start:Number(start),end:Number(end),text:text.join('|').trim()}});if(a.some(x=>!Number.isFinite(x.start)||!Number.isFinite(x.end)||x.start<0||x.end<=x.start||x.end>current().duration||!x.text))throw Error();current().captions=a;save();draw();toast('Captions applied.')}catch{toast('Use start | end | text with times inside this scene.')}};
$('timeTranscript').onclick=()=>{const words=$('transcript').value.trim().split(/\s+/).filter(Boolean);if(!words.length)return;const chunks=[];for(let i=0;i<words.length;i+=8)chunks.push(words.slice(i,i+8).join(' '));current().captions=chunks.map((text,i)=>({start:+(i/chunks.length*current().duration).toFixed(2),end:+((i+1)/chunks.length*current().duration).toFixed(2),text}));save();render();toast('Draft caption timing added. Review against your narration.');};
function srtTime(t){const ms=Math.round(t*1000),s=Math.floor(ms/1000);return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')},${String(ms%1000).padStart(3,'0')}`}
$('exportSrt').onclick=()=>{let offset=0,index=1,blocks=[];for(const s of project.scenes){for(const c of s.captions||[])blocks.push(`${index++}\n${srtTime(offset+c.start)} --> ${srtTime(offset+c.end)}\n${c.text}`);offset+=s.duration}download(new Blob([blocks.join('\n\n')],{type:'text/plain'}),'elleson-captions.srt')};
function parseSrt(str){return str.replace(/\r/g,'').trim().split(/\n\s*\n/).flatMap(b=>{const lines=b.split('\n'),i=lines.findIndex(l=>l.includes('-->'));if(i<0)return [];const m=lines[i].match(/(\d+):(\d+):(\d+)[,.](\d+)\s*-->\s*(\d+):(\d+):(\d+)[,.](\d+)/);if(!m)return [];const t=k=>+m[k]*3600 + +m[k+1]*60 + +m[k+2] + +('0.'+m[k+3]);const start=t(1),end=t(5),text=lines.slice(i+1).join(' ').trim();return start>=0&&end>start&&text?[{start,end,text}]:[]})}
function applyProjectCaptions(captions){let offset=0;for(const s of project.scenes){s.captions=captions.filter(c=>c.end>offset&&c.start<offset+s.duration).map(c=>({start:Math.max(0,c.start-offset),end:Math.min(s.duration,c.end-offset),text:c.text}));offset+=s.duration}save();render()}
$('srtFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;const parsed=parseSrt(await f.text());if(!parsed.length)return toast('No valid SRT captions found.');applyProjectCaptions(parsed);toast('Project captions imported.');};
function playMusic(){if(music){music.currentTime=Math.min(globalTime(),music.duration||0);music.volume=+$('musicVolume').value;music.play().catch(()=>{})}}
async function decodeFile(f){const ac=new AudioContext();try{return await ac.decodeAudioData(await f.arrayBuffer())}finally{await ac.close()}}
$('audioFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;audioBusy=true;try{const buffer=await decodeFile(f);clearAudio();audioURL=URL.createObjectURL(f);audio=new Audio(audioURL);audio.volume=+$('voiceVolume').value;narrationBuffer=buffer;narrationFile=f;$('audioName').textContent=f.name+' · '+buffer.duration.toFixed(1)+'s · session audio';$('clearAudio').hidden=false;drawWaveform();toast('Narration ready. Select a character and enable lip-sync.')}catch{toast('Audio format could not be decoded. Try WAV or MP3.')}finally{audioBusy=false}};
$('clearAudio').onclick=()=>{clearAudio();narrationBuffer=null;narrationFile=null;drawWaveform()};
function clearMusic(){if(music)music.pause();if(musicURL)URL.revokeObjectURL(musicURL);music=null;musicURL=null;musicBuffer=null;musicFile=null;$('musicName').textContent='No music';drawWaveform()}
$('clearMusic').onclick=clearMusic;$('musicFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;audioBusy=true;try{const buffer=await decodeFile(f);clearMusic();musicURL=URL.createObjectURL(f);music=new Audio(musicURL);musicBuffer=buffer;musicFile=f;music.volume=+$('musicVolume').value;$('musicName').textContent=f.name;drawWaveform()}catch{toast('Audio could not be decoded. Try WAV or MP3.')}finally{audioBusy=false}};
